ays in academic, social, and professional endeavors.","Demonstrate competency in designing well -research and well -developed informative and persuasive presentations to a variety of audiences in multiple contexts.","Demonstrate competency in the advocacy of issues of justice and fairness, with integrity and civility.","Demonstrate competency in critical thinking including recognition of common fallacies of thought, effective problem -solving and conflict resolution communication.","Identify crucial issues affecting intercultural communication, and the adaptations necessary for successful interactions between cultures.","Communicate ethically, responsibly, and effectively as local, national and global citizens."],"section_heading":"Communication Studies 2.0 Associate in Arts for Transfer: SC Program: AA-T.4005","total_units":{"max":null,"min":null}}}'::jsonb, '{"arithmetic":"incomplete","coverage":true,"invented":true,"listed":14,"placed":14}'::jsonb, '{"arithmetic":"incomplete","confidence":{"catalog_year":100,"course_list_match":100,"ge_pattern":null,"source":80,"unit_arithmetic":40},"coverage":true,"gaps":["noted_total_cut_off"],"invented":true,"listed":14,"placed":14}'::jsonb)),
c as (select count(*) filter (where r.checked is true) as n,
             coalesce(json_agg(v.i order by v.i) filter (where r.checked is true), '[]'::json) as keys
        from v join public.program_requirement_records r
          on r.college = v.college and r.control_number = v.control_number),
f as (select count(*) as n, coalesce(json_agg(v.i order by v.i), '[]'::json) as keys
        from v join public.program_requirement_records r
          on r.college = v.college and r.control_number = v.control_number
        join lateral (select pv.verdict, pv.requirements_fp from public.program_record_verdicts pv
                       where pv.college = v.college and pv.control_number = v.control_number
                       order by pv.id desc limit 1) lv on true
       where lv.verdict = 'confirm' and lv.requirements_fp = public.program_record_fp(r.record)),
e(expect) as (values (12)),
u as (
update public.program_requirement_records r
   set checks = v.after_checks
  from v
 where r.college = v.college and r.control_number = v.control_number
   and r.extracted_run = v.extracted_run and r.checks = v.before_checks and r.record = v.before_record
   and r.checked is not true
returning v.i),
s as (select count(*) as n, coalesce(json_agg(i order by i), '[]'::json) as keys from u)
select case when f.n > 0
            then ('s739b piles confirm guard: ' || f.n || ' rows hold a matching confirm verdict ' || f.keys::text)::int::text::json
            when s.n = e.expect - c.n
            then json_build_object('returned', s.n, 'keys', s.keys, 'skipped_checked', c.keys)
            else ('s739b piles guard: the UPDATE matched ' || s.n || ' rows, the plan names ' || (e.expect - c.n))::int::text::json end as returned
  from s, c, e, f;
